import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String format = req.getParameter("fmt");

        // Validate report type against allowed list
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query based on report type
        String baseQuery = getBaseQuery(reportType);
        StringBuilder query = new StringBuilder(baseQuery);

        // Apply filters - dates are validated
        if (startDate != null && startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            query.append(" AND created_at >= '").append(startDate).append("'");
        }
        if (endDate != null && endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            query.append(" AND created_at <= '").append(endDate).append("'");
        }

        // Department filter - used for scoping
        if (department != null && !department.isEmpty()) {
            query.append(" AND department = '").append(department).append("'");
        }

        // Order by clause
        String orderBy = req.getParameter("sort");
        if (orderBy != null && !orderBy.isEmpty()) {
            query.append(" ORDER BY ").append(orderBy);
        }

        log.info("Executing report query for type: " + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set query timeout to prevent long-running queries
            stmt.setQueryTimeout(30);

            ResultSet rs = stmt.executeQuery(query.toString());
            resp.setContentType(getContentType(format));

            PrintWriter out = resp.getWriter();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            if ("csv".equals(format)) {
                for (int i = 1; i <= cols; i++) {
                    out.print(meta.getColumnName(i));
                    if (i < cols) out.print(",");
                }
                out.println();
                while (rs.next()) {
                    for (int i = 1; i <= cols; i++) {
                        out.print(rs.getString(i));
                        if (i < cols) out.print(",");
                    }
                    out.println();
                }
            } else {
                out.println("<table>");
                out.println("<tr>");
                for (int i = 1; i <= cols; i++) {
                    out.println("<th>" + meta.getColumnName(i) + "</th>");
                }
                out.println("</tr>");
                while (rs.next()) {
                    out.println("<tr>");
                    for (int i = 1; i <= cols; i++) {
                        out.println("<td>" + rs.getString(i) + "</td>");
                    }
                    out.println("</tr>");
                }
                out.println("</table>");
            }
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory")
                || type.equals("hr") || type.equals("finance"));
    }

    private String getBaseQuery(String type) {
        switch (type) {
            case "sales": return "SELECT id, amount, region, created_at FROM sales_reports WHERE 1=1";
            case "inventory": return "SELECT id, sku, qty, warehouse, created_at FROM inventory_reports WHERE 1=1";
            case "hr": return "SELECT id, emp_name, action, created_at FROM hr_reports WHERE 1=1";
            case "finance": return "SELECT id, account, balance, created_at FROM finance_reports WHERE 1=1";
            default: return "SELECT 1";
        }
    }

    private String getContentType(String format) {
        return "csv".equals(format) ? "text/csv" : "text/html";
    }
}
